mkdir -p /tmp/probe-scripts && cat > /tmp/probe-scripts/fds.js <<'EOF'
const fs=require('fs'),cp=require('child_process');
const C='/opt/driftproof/chrome/chrome-linux64/chrome';
const extra=process.argv.slice(2);
fs.rmSync('/tmp/chrome-probe',{recursive:true,force:true});
const ch=cp.spawn(C,['--headless=new','--no-sandbox','--disable-dev-shm-usage','--disable-gpu','--remote-debugging-port=9333','--user-data-dir=/tmp/chrome-probe',...extra,'about:blank'],{stdio:['ignore','ignore','pipe']});
let err='';ch.stderr.on('data',d=>err+=d);
let best={n:0,sum:{}};let max=0;
const t=setInterval(()=>{
  try{
    const fds=fs.readdirSync(`/proc/${ch.pid}/fd`);
    const sum={};
    for(const f of fds){let l;try{l=fs.readlinkSync(`/proc/${ch.pid}/fd/${f}`)}catch{continue}
      l=l.replace(/\[\d+\]/,'').replace(/\/tmp\/\.?org\.chromium\.Chromium\.\S+/,'SHM').replace(/\/tmp\/chrome-probe\/.*/,'PROFILE:'+l.split('/').pop());
      sum[l]=(sum[l]||0)+1}
    if(fds.length>best.n)best={n:fds.length,sum};
  }catch{}
},5);
const fin=()=>{clearInterval(t);console.log('max fds',best.n,'alive',ch.exitCode===null&&ch.signalCode===null);
  console.log(Object.entries(best.sum).sort((a,b)=>b[1]-a[1]).map(([k,v])=>v+' '+k).join('\n'));
  console.log(err.split('\n').filter(l=>/FATAL|Too many|DevTools/.test(l)).slice(0,4).join('\n'));
  try{ch.kill('SIGKILL')}catch{};process.exit(0)};
ch.on('exit',()=>setTimeout(fin,50));setTimeout(fin,8000);
EOF
